beforeSaveCustomScript:
if (amountGross != null) {
    if (commissionPercent != null && commissionAmount == null) {
        commissionAmount = number\round(amountGross * commissionPercent / 100.0, 2);
        if (amountGrossCurrency != null) {
            commissionAmountCurrency = amountGrossCurrency;
        }
    }
    if (commissionAmount != null && commissionPercent == null && amountGross != 0) {
        commissionPercent = number\round(commissionAmount * 100.0 / amountGross, 4);
    }
    if (commissionAmount != null) {
        amount = number\round(amountGross - commissionAmount, 2);
        if (amount < 0) {
            amount = 0;
        }
        if (amountGrossCurrency != null) {
            amountCurrency = amountGrossCurrency;
        }
    }
}
if (transactionDate == null) {
    transactionDate = datetime\today();
}
if (amount == null) {
    amount = 0;
}
if (entryType == 'Income') {
    amountIn = amount;
    amountOut = 0;
} else if (entryType == 'Expense') {
    amountOut = amount;
    amountIn = 0;
}
if (internalClassification == 'Donation' && donationPaymentReference != null && donationPaymentReference != '') {
    name = string\concatenate(transactionDate, ' | ', donationPaymentReference);
    if (donationDonorCategory != null && donationDonorCategory != '') {
        name = string\concatenate(name, ' | ', donationDonorCategory);
    }
    description = string\concatenate('Donazione ', donationPaymentProvider, ' ordine ', donationPaymentReference);
    if (donationComment != null && donationComment != '') {
        description = string\concatenate(description, '\nComment: ', donationComment);
    }
} else {
    name = string\concatenate(transactionDate, ' — ', description);
}
